import { useMemo, useState } from 'react';
import { Head, router, useForm, usePage } from '@inertiajs/react';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout';
import PageHeader from '@/Components/PageHeader';
import CrudTable from '@/Components/Crud/CrudTable';
import CrudFormModal from '@/Components/Crud/CrudFormModal';
import CrudDetailsModal from '@/Components/Crud/CrudDetailsModal';
import CrudSummaryGrid from '@/Components/Crud/CrudSummaryGrid';
import ConfirmDialog from '@/Components/ConfirmDialog';
import FloatingInput from '@/Components/Form/FloatingInput';
import FloatingSelect from '@/Components/Form/FloatingSelect';
import FloatingTextarea from '@/Components/Form/FloatingTextarea';
import Tooltip from '@/Components/Tooltip';
import ComplianceRichTextEditor from '@/Components/Compliance/ComplianceRichTextEditor';
import { formatReportDate } from '@/Utils/dateFormatters';

const dateLabel = value => formatReportDate(value, '-');
const dateTimeLabel = value => value ? new Date(value).toLocaleString('en-PH', { dateStyle: 'medium', timeStyle: 'short' }) : 'Not sent';
const typeLabel = value => ({ automatic: 'Automatic', manual: 'Manual' }[value] || value);

const PREVIEW_ERROR_MESSAGE = 'Email preview could not be generated. Please try again.';
const NO_PREVIEW_REPORTS_MESSAGE = 'No qualifying reports for this alert type.';

async function readPreviewResponse(response) {
    const body = await response.text();
    let payload = null;
    try {
        payload = body ? JSON.parse(body) : null;
    } catch (error) {
        console.error('Compliance preview returned a non-JSON response.', error);
        throw new Error(PREVIEW_ERROR_MESSAGE);
    }

    if (!response.ok) {
        const message = response.status === 422 && payload?.message === NO_PREVIEW_REPORTS_MESSAGE
            ? payload.message
            : PREVIEW_ERROR_MESSAGE;
        throw new Error(message);
    }

    if (!payload || typeof payload.subject !== 'string' || typeof payload.html !== 'string') {
        console.error('Compliance preview response did not match the JSON contract.', payload);
        throw new Error(PREVIEW_ERROR_MESSAGE);
    }

    return payload;
}

function Card({ label, value, tone = 'green', help = null }) {
    const tones = { green: 'border-green-100 bg-green-50 text-green-800 dark:border-green-900 dark:bg-green-950/40 dark:text-green-200', blue: 'border-blue-100 bg-blue-50 text-blue-800 dark:border-blue-900 dark:bg-blue-950/40 dark:text-blue-200', amber: 'border-amber-100 bg-amber-50 text-amber-800 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-200', red: 'border-red-100 bg-red-50 text-red-800 dark:border-red-900 dark:bg-red-950/40 dark:text-red-200' };
    return <div className={`rounded-2xl border p-5 shadow-sm ${tones[tone]}`}><div className="flex items-center gap-1"><p className="text-xs font-bold uppercase tracking-wide opacity-75">{label}</p>{help && <Tooltip content={help}> <span className="cursor-help text-xs font-extrabold opacity-70" aria-label={`${label} help`}>?</span></Tooltip>}</div><p className="mt-2 text-3xl font-extrabold">{value}</p></div>;
}

const initialRecipient = { protected_area_id: '', target_office: '', recipient_name: '', attention_line: '', recipient_email: '', cc_emails: '', is_active: true, notes: '' };
const initialNonWorkingDay = { date: '', name: '', type: 'NATIONAL_HOLIDAY', scope: 'NATIONAL', location: '', reference: '', remarks: '', is_active: true };

export default function ComplianceAlertsIndex({ view = 'operational', groups = [], complianceScopes = {}, deliveryPlan = { deliveries: [], unmapped: [] }, manualDeliveryPlan = { deliveries: [], unmapped: [] }, recipientReadiness = [], mappingCoverage = [], mappingMetrics = {}, destinationCards = [], monitoredSources = [], activeOverdueSources = [], automaticDeliveryState = {}, summary = {}, runs = [], pendingRecordsVerification = [], pendingMovReports = [], dueSoonReports = [], dueTodayReports = [], confirmationHistory = [], recipients = [], protectedAreas = [], nonWorkingDays = [], settings = null, safeMode = true }) {
    const { auth } = usePage().props;
    const canManage = Boolean(auth?.canManageComplianceAlerts);
    const [tab, setTab] = useState(view === 'recipients' ? 'recipients' : view === 'settings' ? 'settings' : view === 'calendar' ? 'calendar' : 'protected_area');
    const [selected, setSelected] = useState(null);
    const [selectedRecipient, setSelectedRecipient] = useState(null);
    const [selectedRun, setSelectedRun] = useState(null);
    const [selectedPendingVerification, setSelectedPendingVerification] = useState(null);
    const [selectedConfirmation, setSelectedConfirmation] = useState(null);
    const [editingRecipient, setEditingRecipient] = useState(null);
    const [recipientScope, setRecipientScope] = useState('protected_area');
    const [selectedNonWorkingDay, setSelectedNonWorkingDay] = useState(null);
    const [editingNonWorkingDay, setEditingNonWorkingDay] = useState(null);
    const [nonWorkingDayFormOpen, setNonWorkingDayFormOpen] = useState(false);
    const [confirmAction, setConfirmAction] = useState(null);
    const [sending, setSending] = useState(false);
    const [remarks, setRemarks] = useState({});
    const [revocationReasons, setRevocationReasons] = useState({});
    const recipientForm = useForm(initialRecipient);
    const nonWorkingDayForm = useForm(initialNonWorkingDay);
    const settingsForm = useForm(settings || {});
    const [settingsPassword, setSettingsPassword] = useState('');
    const [settingsTab, setSettingsTab] = useState('delivery');
    const [templatePreview, setTemplatePreview] = useState(null);
    const [previewingTemplate, setPreviewingTemplate] = useState(false);
    const activeScope = complianceScopes[tab] || { groups, readiness: recipientReadiness, summary, pending_mov_reports: pendingMovReports, active_overdue_sources: activeOverdueSources };
    const isEngpScope = tab === 'engp';
    const rows = useMemo(() => (activeScope.groups || []).map((group, index) => ({ id: `${group.target_office}-${group.protected_area_name}-${index}`, ...group, overdue_count: group.reports.length, report_not_submitted: group.reports.filter(report => report.compliance_issue === 'Report Not Yet Submitted').length, missing_mov: group.reports.filter(report => report.compliance_issue === 'MOV Not Yet Submitted').length, oldest_deadline: group.reports.reduce((oldest, report) => !oldest || report.deadline < oldest ? report.deadline : oldest, null), max_days_overdue: Math.max(...group.reports.map(report => report.days_overdue)) })), [activeScope]);
    const readinessByKey = useMemo(() => Object.fromEntries((activeScope.readiness || []).map(item => [item.key, item])), [activeScope]);
    const protectedAreaRecipients = useMemo(() => recipients.filter(recipient => Boolean(recipient.protected_area_id)), [recipients]);
    const officeRecipients = useMemo(() => recipients.filter(recipient => !recipient.protected_area_id), [recipients]);
    const resetRecipient = () => { setEditingRecipient(null); setRecipientScope('protected_area'); recipientForm.reset(); recipientForm.clearErrors(); };
    const switchRecipientScope = scope => { setRecipientScope(scope); recipientForm.setData({ ...recipientForm.data, protected_area_id: scope === 'protected_area' ? recipientForm.data.protected_area_id : '', target_office: scope === 'target_office' ? recipientForm.data.target_office : '' }); recipientForm.clearErrors(); };
    const editRecipient = recipient => { setSelectedRecipient(null); setEditingRecipient(recipient); setRecipientScope(recipient.protected_area_id ? 'protected_area' : 'target_office'); recipientForm.setData({ protected_area_id: recipient.protected_area_id || '', target_office: recipient.target_office || '', recipient_name: recipient.recipient_name || '', attention_line: recipient.attention_line ?? '', recipient_email: recipient.recipient_email || '', cc_emails: (recipient.cc_emails || []).join(', '), is_active: Boolean(recipient.is_active), notes: recipient.notes || '' }); recipientForm.clearErrors(); };
    const configureDestination = destination => { const scope = destination.scope || (destination.protected_area_id ? 'protected_area' : 'target_office'); setEditingRecipient(null); setRecipientScope(scope); recipientForm.setData({ ...initialRecipient, protected_area_id: scope === 'protected_area' ? (destination.protected_area_id || '') : '', target_office: scope === 'target_office' ? (destination.target_office || '') : '', is_active: true }); recipientForm.clearErrors(); };
    const submitRecipient = event => { event.preventDefault(); const options = { preserveScroll: true, onSuccess: resetRecipient }; editingRecipient ? recipientForm.put(route('compliance-alerts.recipients.update', editingRecipient.id), options) : recipientForm.post(route('compliance-alerts.recipients.store'), options); };
    const submitSettings = event => { event.preventDefault(); settingsForm.setData('current_password', settingsPassword); settingsForm.put(route('compliance-alerts.settings.update'), { preserveScroll: true, onSuccess: () => setSettingsPassword('') }); };
    const updateTemplateField = (template, field, value) => settingsForm.setData('template_settings', { ...(settingsForm.data.template_settings || {}), [template]: { ...((settingsForm.data.template_settings || {})[template] || {}), [field]: value } });
    const showPreviewError = error => {
        console.error('Compliance email preview failed.', error);
        setTemplatePreview({ error: error?.message === NO_PREVIEW_REPORTS_MESSAGE ? NO_PREVIEW_REPORTS_MESSAGE : PREVIEW_ERROR_MESSAGE });
    };
    const previewDestination = async (destinationKey, alertType) => {
        setTemplatePreview(null);
        setPreviewingTemplate(true);
        try {
            const response = await fetch(route('compliance-alerts.preview', { destination_key: destinationKey, alert_type: alertType }), {
                credentials: 'same-origin',
                headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' },
            });
            setTemplatePreview(await readPreviewResponse(response));
        } catch (error) {
            showPreviewError(error);
        } finally {
            setPreviewingTemplate(false);
        }
    };
    const resetNonWorkingDay = () => { setEditingNonWorkingDay(null); setNonWorkingDayFormOpen(false); nonWorkingDayForm.reset(); nonWorkingDayForm.clearErrors(); };
    const editNonWorkingDay = day => { setSelectedNonWorkingDay(null); setEditingNonWorkingDay(day); setNonWorkingDayFormOpen(true); nonWorkingDayForm.setData({ date: day.date || '', name: day.name || '', type: day.type || 'NATIONAL_HOLIDAY', scope: day.scope || 'NATIONAL', location: day.location || '', reference: day.reference || '', remarks: day.remarks || '', is_active: Boolean(day.is_active) }); nonWorkingDayForm.clearErrors(); };
    const openNonWorkingDayCreate = () => { setEditingNonWorkingDay(null); setNonWorkingDayFormOpen(true); nonWorkingDayForm.setData(initialNonWorkingDay); nonWorkingDayForm.clearErrors(); };
    const submitNonWorkingDay = event => { event.preventDefault(); const options = { preserveScroll: true, onSuccess: resetNonWorkingDay }; editingNonWorkingDay ? nonWorkingDayForm.put(route('compliance-alerts.non-working-days.update', editingNonWorkingDay.id), options) : nonWorkingDayForm.post(route('compliance-alerts.non-working-days.store'), options); };
    const executeAction = () => {
        if (!confirmAction) return;
        setSending(true);
        const finish = () => { setSending(false); setConfirmAction(null); };
         if (confirmAction.type === 'manual') router.post(route('compliance-alerts.send'), {}, { preserveScroll: true, onFinish: finish });
        if (confirmAction.type === 'confirm') router.post(route('compliance-alerts.confirm'), { source_type: confirmAction.report.source_type, source_id: confirmAction.report.source_id, remarks: remarks[`${confirmAction.report.source_type}-${confirmAction.report.source_id}`] || '' }, { preserveScroll: true, onSuccess: () => { setSelectedPendingVerification(null); setTab('history'); }, onFinish: finish });
        if (confirmAction.type === 'unconfirm') router.delete(route('compliance-alerts.unconfirm'), { data: { source_type: confirmAction.report.source_type, source_id: confirmAction.report.source_id, reason: revocationReasons[confirmAction.report.id] || '' }, preserveScroll: true, onSuccess: () => { setSelectedConfirmation(null); setTab('history'); setRevocationReasons(current => ({ ...current, [confirmAction.report.id]: '' })); }, onFinish: finish });
        if (confirmAction.type === 'toggle-recipient') router.patch(route('compliance-alerts.recipients.status', confirmAction.recipient.id), { is_active: !confirmAction.recipient.is_active }, { preserveScroll: true, onFinish: finish });
        if (confirmAction.type === 'delete-recipient') router.delete(route('compliance-alerts.recipients.destroy', confirmAction.recipient.id), { preserveScroll: true, onFinish: finish });
    };
    const paColumns = [
        { key: 'office', label: 'Protected Area / Office', render: row => <><div className="font-bold text-gray-900 dark:text-white">{row.protected_area_name}</div><div className="mt-1 text-xs text-gray-500 dark:text-gray-400">{row.target_office}</div></> },
        { key: 'overdue_count', label: 'Compliance Issues', render: row => <><div>{row.overdue_count} total</div><div className="text-xs text-red-700 dark:text-red-300">Report Not Yet Submitted: {row.report_not_submitted}</div><div className="text-xs text-amber-700 dark:text-amber-300">MOV Not Yet Submitted: {row.missing_mov}</div></> },
        { key: 'oldest_deadline', label: 'Oldest Deadline', render: row => dateLabel(row.oldest_deadline) },
        { key: 'max_days_overdue', label: 'Maximum Days Overdue', render: row => <span className="font-bold text-red-700 dark:text-red-300">{row.max_days_overdue}</span> },
        { key: 'notification_status', label: 'Recipient Readiness', render: row => { const readiness = readinessByKey[row.readiness_key]; const label = readiness?.status === 'ready' ? 'READY' : 'UNMAPPED'; return <><span className={label === 'READY' ? 'font-bold text-green-700 dark:text-green-300' : 'font-bold text-red-700 dark:text-red-300'}>{label}</span><div className="mt-1 text-xs text-gray-500">{readiness?.recipient?.email || 'No valid recipient'}</div></>; } },
        { key: 'last_sent', label: 'Last Sent', render: row => dateTimeLabel(row.last_sent) },
    ];
    const engpColumns = [{ key: 'office', label: 'Implementing Office', render: row => <div className="font-bold text-gray-900 dark:text-white">{row.target_office}</div> }, { key: 'overdue_count', label: 'Compliance Issues', render: row => <><div>{row.overdue_count} pending submission(s)</div><div className="text-xs text-red-700 dark:text-red-300">Not yet received by PENRO: {row.report_not_submitted}</div>{row.missing_mov > 0 && <div className="text-xs text-amber-700 dark:text-amber-300">Supporting document requirement: {row.missing_mov}</div>}</> }, { key: 'oldest_deadline', label: 'Oldest Deadline', render: row => dateLabel(row.oldest_deadline) }, { key: 'max_days_overdue', label: 'Maximum Days Overdue', render: row => <span className="font-bold text-red-700 dark:text-red-300">{row.max_days_overdue}</span> }, { key: 'notification_status', label: 'Recipient Readiness', render: row => { const readiness = readinessByKey[row.readiness_key]; const label = readiness?.status === 'ready' ? 'READY' : 'UNMAPPED'; return <><span className={label === 'READY' ? 'font-bold text-green-700 dark:text-green-300' : 'font-bold text-red-700 dark:text-red-300'}>{label}</span><div className="mt-1 text-xs text-gray-500 dark:text-gray-400">{readiness?.recipient?.email || 'No valid office recipient'}</div></>; } }, { key: 'last_sent', label: 'Last Sent', render: row => dateTimeLabel(row.last_sent) }];
    const recipientDetailsColumns = [
        { key: 'recipient_name', label: 'TO Designation', render: row => <>{row.recipient_name || '-'}<div className="text-xs text-gray-500 dark:text-gray-400">{row.attention_line ? `Attention: ${row.attention_line}` : 'No recipient-specific attention line'}</div><div className="text-xs text-gray-500 dark:text-gray-400">{row.recipient_email}</div></> },
        { key: 'cc_emails', label: 'CC', render: row => (row.cc_emails || []).join(', ') || '-' },
        { key: 'is_active', label: 'Status', render: row => <span className={row.is_active ? 'font-bold text-green-700 dark:text-green-300' : 'font-bold text-gray-500 dark:text-gray-400'}>{row.is_active ? 'Active' : 'Inactive'}</span> },
    ];
    const protectedAreaRecipientColumns = [{ key: 'destination', label: 'Protected Area', render: row => <span className="font-bold text-gray-900 dark:text-white">{row.protected_area_name}</span> }, ...recipientDetailsColumns];
    const officeRecipientColumns = [{ key: 'destination', label: 'Implementing / Target Office', render: row => <span className="font-bold text-gray-900 dark:text-white">{row.target_office}</span> }, ...recipientDetailsColumns];
    const coverageColumns = [{ key: 'destination', label: 'Destination', render: row => <span className="font-bold">{row.destination}</span> }, { key: 'type', label: 'Destination Type' }, { key: 'modules', label: 'Reports / Modules Using It', render: row => <>{row.report_count} report(s)<div className="text-xs text-gray-500 dark:text-gray-400">{(row.modules || []).join(', ')}</div></> }, { key: 'status', label: 'Mapping Status', render: row => <span className={row.status === 'mapped' ? 'font-bold text-green-700 dark:text-green-300' : 'font-bold text-red-700 dark:text-red-300'}>{row.status === 'mapped' ? 'Mapped' : 'No Recipient Mapping'}</span> }, { key: 'recipient', label: 'Recipient', render: row => row.recipient?.email || '—' }, { key: 'action', label: 'Action', render: row => canManage ? <button type="button" onClick={() => row.status === 'mapped' ? editRecipient(recipients.find(item => item.id === row.recipient?.id)) : configureDestination(row)} className="text-xs font-bold text-green-700 dark:text-green-300">{row.status === 'mapped' ? 'Edit' : 'Configure'}</button> : '—' }];
    const nonWorkingDayColumns = [
        { key: 'date', label: 'Date', render: row => dateLabel(row.date) },
        { key: 'name', label: 'Name / Description' },
        { key: 'type', label: 'Type' },
        { key: 'scope', label: 'Scope', render: row => <>{row.scope}{row.location ? <div className="text-xs text-gray-500">{row.location}</div> : null}</> },
        { key: 'is_active', label: 'Status', render: row => <span className={row.is_active ? 'font-bold text-green-700' : 'font-bold text-gray-500'}>{row.is_active ? 'Active' : 'Inactive'}</span> },
    ];
    const historyColumns = [
        { key: 'run_date', label: 'Date / Time', render: row => <>{dateLabel(row.run_date)}<div className="text-xs text-gray-500">{dateTimeLabel(row.sent_at)}</div></> },
        { key: 'run_type', label: 'Type', render: row => typeLabel(row.run_type) },
        { key: 'scope', label: 'Context', render: row => row.scope === 'engp' ? 'ENGP / Development' : row.scope === 'protected_area' ? 'Protected Area' : 'Historical / legacy' },
        { key: 'recipient', label: 'TO Designation', render: row => (row.recipients || []).join(', ') || 'Unmapped' },
        { key: 'report_count', label: 'Reports Included' },
        { key: 'status', label: 'Status', render: row => <span className={row.status === 'sent' ? 'font-bold text-green-700' : row.status === 'failed' ? 'font-bold text-red-700' : 'font-bold text-amber-700'}>{row.status}</span> },
        { key: 'created_by', label: 'Sent By', render: row => row.created_by || (row.run_type === 'automatic' ? 'System' : '-') },
    ];
    const confirmationColumns = [
        { key: 'protected_area', label: 'Protected Area / Office', render: row => <><div className="font-bold text-gray-900 dark:text-white">{row.protected_area_name}</div><div className="text-xs text-gray-500">{row.target_office}</div></> },
        { key: 'module', label: 'Module' },
        { key: 'activity', label: 'Activity' },
        { key: 'document_type', label: 'Document Type' },
        { key: 'deadline', label: 'Deadline', render: row => dateLabel(row.deadline) },
        { key: 'confirmed_by', label: 'Confirmed By' },
        { key: 'confirmed_at', label: 'Confirmed At', render: row => dateTimeLabel(row.confirmed_at) },
        { key: 'status', label: 'Lifecycle Event', render: row => <span className={row.event_type === 'revoked' ? 'font-bold text-amber-700 dark:text-amber-300' : 'font-bold text-green-700 dark:text-green-300'}>{row.event_type === 'revoked' ? 'Revoked' : row.is_current ? 'Confirmed — Current' : 'Confirmed — Historical'}</span> },
    ];
    const pendingVerificationColumns = [
        { key: 'protected_area', label: 'Protected Area / Office', render: row => <><div className="font-bold text-gray-900 dark:text-white">{row.protected_area_name}</div><div className="text-xs text-gray-500">{row.target_office}</div></> },
        { key: 'module', label: 'Module' },
        { key: 'activity', label: 'Activity' },
        { key: 'document_type', label: 'Document Type' },
        { key: 'deadline', label: 'Deadline', render: row => dateLabel(row.deadline) },
        { key: 'submission_date', label: 'PENRO Received / Submission Date', render: row => dateLabel(row.submission_date) },
        { key: 'submission_status', label: 'Submission Status', render: row => <span className="font-bold text-green-700 dark:text-green-300">{row.submission_status}</span> },
        { key: 'records_confirmation', label: 'Records Confirmation', render: () => <span className="font-bold text-amber-700 dark:text-amber-300">Pending</span> },
    ];
    const tabs = view === 'operational' ? [['protected_area', 'Protected Area'], ['engp', 'ENGP / Development'], ['history', 'History']] : [];

    return <AuthenticatedLayout title={view === 'settings' ? 'Compliance Alert Settings' : view === 'recipients' ? 'Recipient Mapping' : view === 'calendar' ? 'Business Calendar' : 'Compliance Alerts'}><Head title={view === 'settings' ? 'Compliance Alert Settings' : view === 'recipients' ? 'Recipient Mapping' : view === 'calendar' ? 'Business Calendar' : 'Compliance Alerts'} />
         <PageHeader title={view === 'settings' ? 'Compliance Alert Settings' : view === 'recipients' ? 'Recipient Mapping' : view === 'calendar' ? 'Business Calendar' : 'Compliance Alerts'} description={view === 'settings' ? 'Configure delivery, destination-aware memorandum templates, signatory details, and operational settings.' : view === 'recipients' ? 'Manage exact Protected Area and Target Office recipient routing mappings.' : view === 'calendar' ? 'Manage holidays and declared non-working days used in report deadline and timeliness calculations.' : 'Separate operational views for Protected Area and ENGP / Development compliance contexts.'} actions={null} />
        {view === 'operational' && safeMode && <div className="mt-5 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-800 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-200">Automatic delivery is disabled by the current production setting. Alerts remain visible and unmapped recipients are not sent.</div>}

        {view === 'operational' && manualDeliveryPlan.unmapped?.length > 0 && <div className="mt-3 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800 dark:border-red-900 dark:bg-red-950/40 dark:text-red-200">{manualDeliveryPlan.unmapped.length} PA / office group(s) have no valid recipient mapping. Automatic delivery will log them as skipped, and Send Now is blocked.</div>}
        {view === 'operational' && <div className="mt-6 flex flex-wrap gap-2 border-b border-gray-200 dark:border-gray-800">{tabs.map(([key, label]) => <button key={key} type="button" onClick={() => setTab(key)} className={`border-b-2 px-4 py-3 text-sm font-bold ${tab === key ? 'border-green-700 text-green-700 dark:text-green-300' : 'border-transparent text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'}`}>{label}</button>)}</div>}
        {['protected_area', 'engp'].includes(tab) && <>
            <div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-6"><Card label="Due Within 3 Days" value={activeScope.summary?.due_soon ?? 0} tone="amber" help="Reports with an authoritative deadline after today and within the configured calendar-date reminder window." /><Card label="Due Today" value={activeScope.summary?.due_today ?? 0} tone="amber" /><Card label="Overdue" value={activeScope.summary?.overdue_reports ?? 0} tone="red" /><Card label="No Recipient Mapping" value={activeScope.summary?.unmapped_destinations ?? 0} tone="red" /><Card label="Alerts Sent Today" value={activeScope.summary?.sent_today ?? 0} /><Card label={isEngpScope ? 'Affected Implementing Offices' : 'Affected Protected Areas / Offices'} value={activeScope.summary?.affected_groups ?? 0} tone="blue" /></div>
            <section className="mt-6 rounded-2xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900"><div className="flex flex-wrap items-baseline justify-between gap-2"><h2 className="text-sm font-extrabold text-gray-900 dark:text-white">{isEngpScope ? 'Active ENGP / Development Compliance Sources' : 'Active Protected Area Compliance Sources'}</h2><span className="text-xs font-semibold text-gray-500 dark:text-gray-400">{(activeScope.active_overdue_sources || []).length} workflow(s) currently overdue</span></div>{(activeScope.active_overdue_sources || []).length ? <div className="mt-3 flex flex-wrap gap-2">{activeScope.active_overdue_sources.map(source => <span key={source.module} className="rounded-full bg-red-50 px-3 py-1.5 text-xs font-semibold text-red-800 dark:bg-red-950/50 dark:text-red-200">{source.module}: {source.overdue_count} pending</span>)}</div> : <p className="mt-3 text-sm text-gray-500 dark:text-gray-400">{isEngpScope ? 'No ENGP / Development reports are currently overdue.' : 'No Protected Area reports are currently overdue.'}</p>}</section>
            <div className="mt-6"><CrudTable title={isEngpScope ? 'Overdue ENGP / Development Reports' : 'Overdue Protected Area Reports'} subtitle={isEngpScope ? 'Regular ENGP monitoring and accomplishment reports awaiting PENRO submission or receipt.' : 'Protected Area reports past deadline without PENRO receipt, including applicable MOV compliance.'} helperText={isEngpScope ? 'ENGP records are grouped by implementing office and retain their existing workflow semantics.' : 'PA reports past deadline without PENRO receipt and submitted reports with overdue MOVs remain active.'} columns={isEngpScope ? engpColumns : paColumns} rows={rows} rowKey="id" onRowClick={row => setSelected({ ...row, scope: tab })} emptyTitle={isEngpScope ? 'No overdue ENGP / Development reports today' : 'No overdue Protected Area reports today'} emptyDescription="All current reports in this compliance context are within deadline or complete." tableClassName="min-w-[1050px]" /></div>
            {!isEngpScope && (activeScope.pending_mov_reports || []).length > 0 && <div className="mt-6"><CrudTable title="MOV Not Yet Submitted" subtitle="Protected Area submissions with applicable MOV requirements remain visible until supporting evidence is complete." columns={[{ key: 'office', label: 'Protected Area / Office', render: row => <><div className="font-bold">{row.protected_area_name}</div><div className="text-xs text-gray-500 dark:text-gray-400">{row.target_office}</div></> }, { key: 'module', label: 'Module' }, { key: 'activity', label: 'Activity' }, { key: 'deadline', label: 'Deadline', render: row => dateLabel(row.deadline) }, { key: 'mov_status', label: 'MOV Status', render: () => <span className="font-bold text-amber-700 dark:text-amber-300">MOV Not Yet Submitted</span> }]} rows={activeScope.pending_mov_reports} rowKey={row => `${row.source_type}-${row.source_id}`} emptyTitle="No MOV Not Yet Submitted" emptyDescription="No PA submissions are waiting for MOV submission." tableClassName="min-w-[1000px]" /></div>}
        </>}
        {tab === 'recipients' && canManage && <div className="mt-6 space-y-6"><section className="rounded-2xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900"><div className="flex flex-wrap gap-5 text-sm"><span><strong>Active Recipient Mappings:</strong> {mappingMetrics.active_mappings ?? 0}</span><span><strong>Destination Coverage:</strong> {mappingMetrics.mapped ?? 0} mapped / {mappingMetrics.unmapped ?? 0} unmapped</span></div></section><CrudTable title="Destination Coverage" subtitle="Distinct destinations referenced by active report workflows. One PA or target-office mapping serves every module using that destination." columns={coverageColumns} rows={mappingCoverage} rowKey="key" emptyTitle="No report destinations yet" emptyDescription="Coverage appears automatically as report records are created." tableClassName="min-w-[980px]" /><div className="grid gap-6 xl:grid-cols-[1.35fr_0.85fr]">
            <div className="space-y-6"><CrudTable title="Protected Area Recipient Mappings" subtitle="Used by Protected Area-based report workflows. Protected Area is the mapping identity." columns={protectedAreaRecipientColumns} rows={protectedAreaRecipients} rowKey="id" onRowClick={setSelectedRecipient} emptyTitle="No Protected Area recipient mappings" emptyDescription="Zero mappings is valid; configure a Protected Area when ready." tableClassName="min-w-[780px]" /><CrudTable title="Development / ENGP Office Recipient Mappings" subtitle="Used by ENGP and office-scoped Development workflows. Protected Area is not applicable." columns={officeRecipientColumns} rows={officeRecipients} rowKey="id" onRowClick={setSelectedRecipient} emptyTitle="No office recipient mappings" emptyDescription="Configure an implementing or target office when ready." tableClassName="min-w-[780px]" /></div>
            <form onSubmit={submitRecipient} className="space-y-4 rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900"><div className="flex items-center justify-between"><h2 className="font-bold text-gray-900 dark:text-white">{editingRecipient ? `Edit ${recipientScope === 'protected_area' ? 'Protected Area' : 'Office'} Recipient` : `Add ${recipientScope === 'protected_area' ? 'Protected Area' : 'Office'} Recipient`}</h2>{editingRecipient && <button type="button" onClick={resetRecipient} className="text-xs font-bold text-gray-500 dark:text-gray-400">Cancel</button>}</div>
                <div className="grid grid-cols-2 gap-2 rounded-xl border border-gray-200 bg-gray-50 p-1 dark:border-gray-700 dark:bg-gray-800"><button type="button" onClick={() => switchRecipientScope('protected_area')} className={`rounded-lg px-3 py-2 text-xs font-bold ${recipientScope === 'protected_area' ? 'bg-green-700 text-white' : 'text-gray-600 dark:text-gray-300'}`}>Protected Area</button><button type="button" onClick={() => switchRecipientScope('target_office')} className={`rounded-lg px-3 py-2 text-xs font-bold ${recipientScope === 'target_office' ? 'bg-green-700 text-white' : 'text-gray-600 dark:text-gray-300'}`}>Development / ENGP Office</button></div>
                {recipientScope === 'protected_area' ? <><p className="text-xs text-gray-500 dark:text-gray-400">For PA-based workflows, the Protected Area is authoritative.</p><FloatingSelect label="Protected Area" required value={recipientForm.data.protected_area_id} error={recipientForm.errors.protected_area_id} onChange={event => recipientForm.setData('protected_area_id', event.target.value)}><option value="">Select Protected Area</option>{protectedAreas.map(area => <option key={area.id} value={area.id}>{area.name}</option>)}</FloatingSelect></> : <><p className="text-xs text-gray-500 dark:text-gray-400">For ENGP and office-scoped Development workflows, use the implementing / target office. No Protected Area is required.</p><FloatingInput label="Implementing / Target Office" required value={recipientForm.data.target_office} onChange={event => recipientForm.setData('target_office', event.target.value)} error={recipientForm.errors.target_office} /></>}
                <FloatingInput label="TO Designation" value={recipientForm.data.recipient_name} onChange={event => recipientForm.setData('recipient_name', event.target.value)} />
                <FloatingInput label="Attention Designation (optional mapping override)" value={recipientForm.data.attention_line} onChange={event => recipientForm.setData('attention_line', event.target.value)} error={recipientForm.errors.attention_line} />
                <FloatingInput label="Recipient Email" type="email" required value={recipientForm.data.recipient_email} onChange={event => recipientForm.setData('recipient_email', event.target.value)} error={recipientForm.errors.recipient_email} />
                <FloatingInput label="CC Emails (comma separated)" value={recipientForm.data.cc_emails} onChange={event => recipientForm.setData('cc_emails', event.target.value)} error={recipientForm.errors.cc_emails} />
                <FloatingSelect label="Status" value={recipientForm.data.is_active ? '1' : '0'} onChange={event => recipientForm.setData('is_active', event.target.value === '1')}><option value="1">Active</option><option value="0">Inactive</option></FloatingSelect>
                <FloatingTextarea label="Notes" rows={3} value={recipientForm.data.notes} onChange={event => recipientForm.setData('notes', event.target.value)} />
                <button type="submit" disabled={recipientForm.processing} className="w-full rounded-xl bg-green-700 px-4 py-3 text-xs font-bold text-white disabled:opacity-50">{editingRecipient ? 'Save Recipient' : 'Add Recipient'}</button>
            </form>
        </div></div>}
        {tab === 'history' && <div className="mt-6 space-y-6"><CrudTable title="Notification History" subtitle="Run snapshots retain the reports and delivery content as they existed at send time." columns={historyColumns} rows={runs} rowKey="id" onRowClick={setSelectedRun} emptyTitle="No notification history" emptyDescription="Automatic and manual production activity will be recorded here. Historical legacy rows remain available for audit." tableClassName="w-full min-w-[900px] table-fixed" /><CrudTable title="Pending Records Verification" subtitle="Submitted reports await audit verification here. Reports with MOV not yet submitted may remain active until supporting evidence is complete." columns={pendingVerificationColumns} rows={pendingRecordsVerification} rowKey={row => `${row.source_type}-${row.source_id}`} onRowClick={setSelectedPendingVerification} emptyTitle="No pending Records verification" emptyDescription="All submitted reports are confirmed, or no submitted reports require verification." tableClassName="min-w-[1200px]" /><CrudTable title="Records Confirmation History" subtitle="Immutable confirmation and revocation events remain visible here and do not affect memorandum eligibility." columns={confirmationColumns} rows={confirmationHistory} rowKey="id" onRowClick={setSelectedConfirmation} emptyTitle="No Records confirmations" emptyDescription="Confirmation and revocation events will appear here." tableClassName="min-w-[1100px]" /></div>}
          {view === 'settings' && canManage && <DestinationCards cards={destinationCards} onPreview={previewDestination} previewing={previewingTemplate} />}
         {view === 'settings' && <div className="mb-5 flex flex-wrap gap-1 rounded-xl border border-gray-200 bg-gray-50 p-1 dark:border-gray-700 dark:bg-gray-900">{[['delivery', 'Delivery'], ['protected_area_templates', 'Protected Area Templates'], ['engp_templates', 'ENGP Templates'], ['sender', 'Sender & Footer']].map(([key, label]) => <button key={key} type="button" onClick={() => setSettingsTab(key)} className={`rounded-lg px-3 py-2 text-xs font-bold transition sm:px-4 ${settingsTab === key ? 'bg-green-700 text-white shadow-sm' : 'text-gray-600 hover:bg-white hover:text-gray-900 dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-white'}`}>{label}</button>)}</div>}
         {tab === 'settings' && view === 'settings' && canManage && settings && <form onSubmit={submitSettings} className="mt-6 space-y-6">{settingsTab === 'delivery' && <SettingsSection title="Delivery"><div className="grid gap-4 md:grid-cols-2"><FloatingSelect label="Alerts" value={settingsForm.data.alerts_enabled ? '1' : '0'} onChange={event => settingsForm.setData('alerts_enabled', event.target.value === '1')}><option value="0">Disabled</option><option value="1">Enabled</option></FloatingSelect><FloatingSelect label="Automatic Email Delivery" value={settingsForm.data.automatic_send_enabled ? '1' : '0'} onChange={event => settingsForm.setData('automatic_send_enabled', event.target.value === '1')}><option value="0">OFF</option><option value="1">ON</option></FloatingSelect><FloatingInput label="Reminder Lead Time (days)" value="3" disabled /><FloatingInput label="Send Time" type="time" required value={settingsForm.data.send_time || ''} onChange={event => settingsForm.setData('send_time', event.target.value)} /><FloatingInput label="Timezone (fixed)" required disabled value={settingsForm.data.timezone || 'Asia/Manila'} error={settingsForm.errors.timezone} /></div><div className="mt-5 rounded-xl border border-blue-200 bg-blue-50/60 p-4 dark:border-blue-900 dark:bg-blue-950/30"><h3 className="text-xs font-extrabold uppercase tracking-wide text-blue-900 dark:text-blue-100">Operational Status</h3><p className="mt-1 text-xs text-blue-800 dark:text-blue-200">Automatic delivery uses only active recipient mappings and the current report eligibility rules.</p><div className="mt-4 rounded-xl border border-gray-200 p-4 text-sm dark:border-gray-700"><div className="flex flex-wrap gap-x-6 gap-y-2"><span><strong>Automatic Delivery:</strong> {automaticDeliveryState.effective ? "Enabled" : "Disabled"}</span><span><strong>Server Delivery Gate:</strong> {automaticDeliveryState.environment_gate ? "Enabled" : "Disabled"}</span><span><strong>Mail Configuration:</strong> {automaticDeliveryState.mail_configured ? "Configured" : "Not configured"}</span><span><strong>Recipient Mapping Readiness:</strong> {recipientReadiness.filter(item => item.status === "ready").length} mapped / {recipientReadiness.filter(item => item.status === "unmapped").length} unmapped</span></div>{!automaticDeliveryState.environment_gate && <p className="mt-3 font-semibold text-amber-700 dark:text-amber-300">Automatic delivery cannot be enabled because the server delivery gate is disabled.</p>}{Boolean(settings?.automatic_send_enabled) !== Boolean(settingsForm.data.automatic_send_enabled) && <div className="mt-4 max-w-md"><FloatingInput label="Current password" type="password" required value={settingsPassword} onChange={event => setSettingsPassword(event.target.value)} error={settingsForm.errors.current_password || settingsForm.errors.automatic_send_enabled} /></div>}</div></div></SettingsSection>}
             {settingsTab === 'protected_area_templates' && <TemplateEditors title="Protected Area Templates" description="PA-specific message wording only. Destination, TO designation, attention, email, and CC always come from the selected recipient mapping." templates={['protected_area_due_soon', 'protected_area_overdue']} templateSettings={settingsForm.data.template_settings || {}} onChange={updateTemplateField} />}
             {settingsTab === 'engp_templates' && <TemplateEditors title="ENGP Templates" description="Independent implementing-office message wording only. Destination and recipient identity always come from the selected office mapping." templates={['engp_due_soon', 'engp_overdue']} templateSettings={settingsForm.data.template_settings || {}} onChange={updateTemplateField} />}
            {settingsTab === 'sender' && <SettingsSection title="Signatory"><div className="grid gap-4 md:grid-cols-2"><FloatingInput label="Signatory Name" required value={settingsForm.data.signatory_name || ''} onChange={event => settingsForm.setData('signatory_name', event.target.value)} /><FloatingInput label="Signatory Position" required value={settingsForm.data.signatory_position || ''} onChange={event => settingsForm.setData('signatory_position', event.target.value)} /><FloatingInput label="Office Name" required value={settingsForm.data.office_name || ''} onChange={event => settingsForm.setData('office_name', event.target.value)} /><FloatingInput label="Office Address" required value={settingsForm.data.office_address || ''} onChange={event => settingsForm.setData('office_address', event.target.value)} /></div></SettingsSection>}
            {settingsTab === 'sender' && <SettingsSection title="Contact / Footer"><div className="grid gap-4 md:grid-cols-2"><FloatingInput label="Email From Name (configured in .env)" disabled value={settingsForm.data.mail_from_name || ''} /><FloatingInput label="Focal Person Name" value={settingsForm.data.focal_person_name || ''} onChange={event => settingsForm.setData('focal_person_name', event.target.value)} /><FloatingInput label="Focal Person Position" value={settingsForm.data.focal_person_position || ''} onChange={event => settingsForm.setData('focal_person_position', event.target.value)} /></div><div className="mt-4 grid gap-4"><FloatingTextarea label="Focal Person Contact / Context" rows={3} value={settingsForm.data.focal_person_contact || ''} onChange={event => settingsForm.setData('focal_person_contact', event.target.value)} /><ComplianceRichTextEditor label="Do Not Reply Text" value={settingsForm.data.do_not_reply_text || ''} onChange={value => settingsForm.setData('do_not_reply_text', value)} error={settingsForm.errors.do_not_reply_text} placeholder="PLEASE DO NOT REPLY." /><ComplianceRichTextEditor label="System-generated Footer" value={settingsForm.data.system_generated_footer_text || ''} onChange={value => settingsForm.setData('system_generated_footer_text', value)} error={settingsForm.errors.system_generated_footer_text} placeholder="System-generated notification text." /></div></SettingsSection>}

            <button type="submit" disabled={settingsForm.processing} className="rounded-xl bg-green-700 px-5 py-3 text-xs font-bold text-white disabled:opacity-50">Save Settings</button>
        </form>}
        <CrudDetailsModal open={Boolean(templatePreview)} icon="✉" title="Email Preview" subtitle={templatePreview?.subject || 'Template preview'} onClose={() => setTemplatePreview(null)} summary={templatePreview && <CrudSummaryGrid items={[{ label: 'Email Subject', value: templatePreview.subject || 'Preview unavailable' }]} />}><div className="space-y-3">{templatePreview?.error ? <p className="rounded-lg bg-red-50 p-3 text-sm text-red-800 dark:bg-red-950/40 dark:text-red-200">{templatePreview.error}</p> : <iframe title="Rendered email preview" sandbox="" srcDoc={templatePreview?.html || ''} className="h-[620px] w-full rounded-lg border border-gray-200 bg-white dark:border-gray-700" />}</div></CrudDetailsModal>        {tab === 'calendar' && view === 'calendar' && <div className="mt-6"><SettingsSection title="Non-Working Days"><p className="mb-3 text-xs text-gray-500 dark:text-gray-400">Configured active national, Davao Oriental, and office-declared dates. PAMB calculations use Monday-Thursday working days and exclude these configured dates.</p><button type="button" onClick={openNonWorkingDayCreate} className="mb-4 rounded-xl bg-green-700 px-4 py-2.5 text-xs font-bold text-white">+ Add Non-Working Day</button><CrudTable title="Configured Calendar Dates" subtitle={`${nonWorkingDays.length} configured dates`} helperText="Click any row to view details" columns={nonWorkingDayColumns} rows={nonWorkingDays} rowKey="id" onRowClick={setSelectedNonWorkingDay} emptyTitle="No configured non-working days" emptyDescription="No holiday or special non-working dates have been registered." tableClassName="min-w-[900px]" /></SettingsSection></div>}
        <CrudDetailsModal open={Boolean(selected)} icon="!" title={selected?.scope === 'engp' ? 'ENGP / Development Report Details' : 'Protected Area Report Details'} subtitle={selected ? (selected.scope === 'engp' ? selected.target_office : `${selected.protected_area_name} - ${selected.target_office}`) : ''} onClose={() => setSelected(null)} summary={selected && <CrudSummaryGrid items={[{ label: 'Compliance Issues', value: selected.overdue_count }, { label: 'Report Not Yet Submitted', value: selected.report_not_submitted }, ...(selected.scope !== 'engp' ? [{ label: 'MOV Not Yet Submitted', value: selected.missing_mov }] : []), { label: 'Oldest Deadline', value: dateLabel(selected.oldest_deadline) }, { label: 'Maximum Days Overdue', value: selected.max_days_overdue }, { label: 'Notification', value: safeMode ? 'Safe mode' : 'Ready' }]} />}><div className="space-y-3">{selected?.reports.map((report, index) => <div key={`${report.source_type}-${report.source_id}`} className="rounded-xl border border-gray-200 p-4 dark:border-gray-700"><div className="flex flex-col justify-between gap-3 sm:flex-row"><div><p className="font-bold text-gray-900 dark:text-white">{index + 1}. {report.activity}</p><p className="mt-1 text-xs text-gray-500">Module: {report.module.replace(/ Report Submission Tracker$/, "")}</p><p className="text-xs text-gray-500">Document Type: {report.document_type}</p><p className={`mt-1 text-xs font-bold ${report.compliance_issue === 'MOV Not Yet Submitted' ? 'text-amber-700' : 'text-red-700'}`}>Compliance Issue: {report.compliance_issue}</p></div><span className="text-sm font-bold text-red-700 dark:text-red-300">{report.days_overdue} day(s) overdue</span></div><dl className="mt-3 grid gap-2 text-xs sm:grid-cols-3"><div><dt className="font-semibold text-gray-500">Deadline</dt><dd>{dateLabel(report.deadline)}</dd></div>{report.reporting_period && <div><dt className="font-semibold text-gray-500">Reporting Period</dt><dd>{report.reporting_period}</dd></div>}<div><dt className="font-semibold text-gray-500">PENRO Received</dt><dd>{dateLabel(report.submission_date)}</dd></div><div><dt className="font-semibold text-gray-500">Submission Status</dt><dd>{report.submission_status}</dd></div>{(selected?.scope !== 'engp' || report.mov_required) && <div><dt className="font-semibold text-gray-500">MOV Status</dt><dd>{report.mov_present ? `${report.mov_label} Submitted` : `${report.mov_label} Not Yet Submitted`}</dd></div>}<div><dt className="font-semibold text-gray-500">Records confirmation</dt><dd>{report.records_confirmed ? `Confirmed by ${report.records_confirmed_by || 'Records'} on ${dateTimeLabel(report.records_confirmed_at)}` : 'Pending'}</dd></div></dl>{report.records_confirmation_remarks && <p className="mt-2 text-xs text-gray-600 dark:text-gray-300">Remarks: {report.records_confirmation_remarks}</p>}{canManage && <div className="mt-3">{report.records_confirmed ? <button type="button" onClick={() => setConfirmAction({ type: 'unconfirm', report })} className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800 hover:bg-amber-100">Remove Records Confirmation</button> : report.submitted ? <><FloatingTextarea label="Records Remarks (optional)" rows={2} value={remarks[`${report.source_type}-${report.source_id}`] || ''} onChange={event => setRemarks(current => ({ ...current, [`${report.source_type}-${report.source_id}`]: event.target.value }))} /><button type="button" onClick={() => setConfirmAction({ type: 'confirm', report })} className="mt-2 rounded-lg bg-green-700 px-3 py-2 text-xs font-bold text-white hover:bg-green-800">Confirm Records Receipt</button></> : <p className="text-xs font-semibold text-gray-500">Records confirmation is available only after the report has been submitted.</p>}</div>}</div>)}</div></CrudDetailsModal>
        <CrudDetailsModal open={Boolean(selectedPendingVerification)} icon="✓" title="Pending Records Verification" subtitle={selectedPendingVerification ? `${selectedPendingVerification.protected_area_name} - ${selectedPendingVerification.target_office}` : ''} onClose={() => setSelectedPendingVerification(null)} summary={selectedPendingVerification && <CrudSummaryGrid items={[{ label: 'Module', value: selectedPendingVerification.module }, { label: 'Submission Status', value: selectedPendingVerification.submission_status }, { label: 'Records Confirmation', value: 'Pending' }]} />}><div className="space-y-3 text-sm"><p><span className="font-bold">Activity:</span> {selectedPendingVerification?.activity}</p><p><span className="font-bold">Document Type:</span> {selectedPendingVerification?.document_type}</p><p><span className="font-bold">Deadline:</span> {dateLabel(selectedPendingVerification?.deadline)}</p><p><span className="font-bold">PENRO Received / Submission Date:</span> {dateLabel(selectedPendingVerification?.submission_date)}</p><p className="rounded-lg bg-blue-50 p-3 text-xs text-blue-800 dark:bg-blue-950/40 dark:text-blue-200">This report is submitted and awaits Records verification. If its MOV is missing and the deadline has passed, it may remain active as a MOV Not Yet Submitted alert until supporting evidence is complete.</p>{canManage && <><FloatingTextarea label="Records Remarks (optional)" rows={2} value={remarks[`${selectedPendingVerification?.source_type}-${selectedPendingVerification?.source_id}`] || ''} onChange={event => setRemarks(current => ({ ...current, [`${selectedPendingVerification?.source_type}-${selectedPendingVerification?.source_id}`]: event.target.value }))} /><button type="button" onClick={() => setConfirmAction({ type: 'confirm', report: selectedPendingVerification })} className="rounded-lg bg-green-700 px-3 py-2 text-xs font-bold text-white hover:bg-green-800">Confirm Records Receipt</button></>}</div></CrudDetailsModal>
        <CrudDetailsModal open={Boolean(selectedRun)} icon="#" title="Notification Run Details" subtitle={selectedRun ? `${typeLabel(selectedRun.run_type)} - ${selectedRun.status}` : ''} onClose={() => setSelectedRun(null)} summary={selectedRun && <CrudSummaryGrid items={[{ label: 'TO Designation', value: (selectedRun.recipients || []).join(', ') || 'Unmapped' }, { label: 'Reports', value: selectedRun.report_count }, { label: 'Sent By', value: selectedRun.created_by || 'System' }, { label: 'Sent At', value: dateTimeLabel(selectedRun.sent_at) }]} />}><div className="space-y-3">{selectedRun?.error_message && <p className="rounded-lg bg-amber-50 p-3 text-sm text-amber-800">{selectedRun.error_message}</p>}{selectedRun?.reports?.map((report, index) => <div key={`${report.source_type}-${report.source_id}-${index}`} className="rounded-xl border border-gray-200 p-3 text-sm dark:border-gray-700"><div className="font-bold">{report.module}: {report.activity}</div><div className="mt-1 text-xs text-gray-500">{report.document_type} - {dateLabel(report.deadline)} - {report.days_overdue} day(s) overdue at run time</div></div>)}</div></CrudDetailsModal>
        <CrudDetailsModal open={Boolean(selectedRecipient)} icon="@" title="Recipient Details" subtitle={selectedRecipient ? `${selectedRecipient.is_active ? 'ACTIVE' : 'INACTIVE'} mapping` : ''} onClose={() => setSelectedRecipient(null)} summary={selectedRecipient && <CrudSummaryGrid items={[{ label: 'Mapping Type', value: selectedRecipient.protected_area_id ? 'Protected Area' : 'Development / ENGP Office' }, { label: selectedRecipient.protected_area_id ? 'Protected Area' : 'Implementing / Target Office', value: selectedRecipient.protected_area_id ? selectedRecipient.protected_area_name : selectedRecipient.target_office }, { label: 'Status', value: selectedRecipient.is_active ? 'ACTIVE' : 'INACTIVE' }]} />}><div className="space-y-2 text-sm"><p><span className="font-bold">TO Designation:</span> {selectedRecipient?.recipient_name || 'Not configured'}</p><p><span className="font-bold">Attention Designation:</span> {selectedRecipient?.attention_line || 'Not configured'}</p><p><span className="font-bold">Recipient Email:</span> {selectedRecipient?.recipient_email}</p><p><span className="font-bold">CC Emails:</span> {(selectedRecipient?.cc_emails || []).join(', ') || 'None'}</p><p><span className="font-bold">Notes:</span> {selectedRecipient?.notes || 'None.'}</p><p><span className="font-bold">Created:</span> {dateTimeLabel(selectedRecipient?.created_at)}</p><p><span className="font-bold">Updated:</span> {dateTimeLabel(selectedRecipient?.updated_at)}</p></div><div className="mt-5 flex flex-wrap gap-2"><button type="button" onClick={() => editRecipient(selectedRecipient)} className="rounded-lg bg-green-700 px-3 py-2 text-xs font-bold text-white">Edit</button><button type="button" onClick={() => setConfirmAction({ type: 'toggle-recipient', recipient: selectedRecipient })} className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800 dark:border-amber-800 dark:bg-amber-950/40 dark:text-amber-200">{selectedRecipient?.is_active ? 'Deactivate' : 'Activate'}</button><button type="button" onClick={() => setConfirmAction({ type: 'delete-recipient', recipient: selectedRecipient })} className="rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-xs font-bold text-red-800 dark:border-red-800 dark:bg-red-950/40 dark:text-red-200">Delete</button></div></CrudDetailsModal>
        <CrudDetailsModal open={Boolean(selectedConfirmation)} icon="✓" title="Records Confirmation Details" subtitle={selectedConfirmation?.location_label || ""} onClose={() => setSelectedConfirmation(null)} summary={selectedConfirmation && <CrudSummaryGrid items={[{ label: "Module", value: selectedConfirmation.module_name || selectedConfirmation.module }, { label: "Office / Protected Area", value: selectedConfirmation.location_label || selectedConfirmation.target_office || selectedConfirmation.protected_area_name }, ...(selectedConfirmation.reporting_period ? [{ label: "Reporting Period", value: selectedConfirmation.reporting_period }] : []), { label: "Confirmed By", value: selectedConfirmation.confirmed_by }, { label: "Confirmed At", value: dateTimeLabel(selectedConfirmation.confirmed_at) }, ...(selectedConfirmation.event_type === "revoked" ? [{ label: "Status", value: "Revoked" }] : [])]} />}><div className="space-y-3 text-sm">{selectedConfirmation?.remarks && <p><span className="font-bold">Remarks:</span> {selectedConfirmation.remarks}</p>}{selectedConfirmation?.event_type === "revoked" && <div className="space-y-2"><p><span className="font-bold">Revoked By:</span> {selectedConfirmation.revoked_by || "Unknown user"}</p><p><span className="font-bold">Revoked At:</span> {dateTimeLabel(selectedConfirmation.revoked_at)}</p><p><span className="font-bold">Revocation Reason:</span> {selectedConfirmation.revocation_reason}</p></div>}{canManage && selectedConfirmation?.event_type === "confirmed" && selectedConfirmation?.is_current && <div className="mt-4 space-y-2"><FloatingTextarea label="Revocation Reason" required rows={3} value={revocationReasons[selectedConfirmation.id] || ""} onChange={event => setRevocationReasons(current => ({ ...current, [selectedConfirmation.id]: event.target.value }))} /><button type="button" disabled={!String(revocationReasons[selectedConfirmation.id] || "").trim()} onClick={() => setConfirmAction({ type: "unconfirm", report: selectedConfirmation })} className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs font-bold text-amber-800 disabled:cursor-not-allowed disabled:opacity-50">Revoke Records Confirmation</button></div>}</div></CrudDetailsModal>
         <ConfirmDialog open={Boolean(confirmAction)} title={confirmAction?.type === 'manual' ? 'Send compliance memorandum?' : confirmAction?.type === 'unconfirm' ? 'Remove Records confirmation?' : confirmAction?.type === 'toggle-recipient' ? `${confirmAction?.recipient?.is_active ? 'Deactivate' : 'Activate'} recipient mapping?` : confirmAction?.type === 'delete-recipient' ? 'Delete unused recipient mapping?' : 'Confirm Records receipt?'} message={confirmAction?.type === 'manual' ? `This sends ${manualDeliveryPlan.deliveries?.reduce((total, item) => total + item.report_count, 0) || 0} current due-soon, due-today, and overdue report(s) to ${manualDeliveryPlan.deliveries?.map(item => item.recipient.email).join(', ')}.` : confirmAction?.type === 'unconfirm' ? 'Use this only to correct an inaccurate Records confirmation. Removing it returns the submitted report to Pending Records Verification only.' : confirmAction?.type === 'toggle-recipient' ? `This will ${confirmAction?.recipient?.is_active ? 'stop' : 'restore'} production resolution for ${confirmAction?.recipient?.target_office || confirmAction?.recipient?.protected_area_name}. Existing notification history will not be changed.` : confirmAction?.type === 'delete-recipient' ? 'Only unused mappings may be deleted. If notification history references this mapping, deletion will be blocked and deactivation should be used instead.' : 'This report is already submitted. Confirm its Records receipt to move it to Records Confirmation History; this does not affect alert or memorandum eligibility.'} confirmLabel={confirmAction?.type === 'manual' ? 'Send Now' : confirmAction?.type === 'unconfirm' ? 'Remove Confirmation' : confirmAction?.type === 'toggle-recipient' ? (confirmAction?.recipient?.is_active ? 'Deactivate' : 'Activate') : confirmAction?.type === 'delete-recipient' ? 'Delete Mapping' : 'Confirm Receipt'} processing={sending} onConfirm={executeAction} onCancel={() => !sending && setConfirmAction(null)} />
        <CrudDetailsModal open={Boolean(selectedNonWorkingDay)} icon="∷" title="Non-Working Day Details" subtitle={selectedNonWorkingDay ? dateLabel(selectedNonWorkingDay.date) : ''} onClose={() => setSelectedNonWorkingDay(null)} summary={selectedNonWorkingDay && <CrudSummaryGrid items={[{ label: 'Date', value: dateLabel(selectedNonWorkingDay.date) }, { label: 'Type', value: selectedNonWorkingDay.type }, { label: 'Scope', value: selectedNonWorkingDay.scope }, { label: 'Status', value: selectedNonWorkingDay.is_active ? 'Active' : 'Inactive' }]} />}><div className="space-y-2 text-sm"><p><span className="font-bold">Name / Description:</span> {selectedNonWorkingDay?.name}</p><p><span className="font-bold">Scope:</span> {selectedNonWorkingDay?.scope}{selectedNonWorkingDay?.location ? ` — ${selectedNonWorkingDay.location}` : ''}</p><p><span className="font-bold">Reference:</span> {selectedNonWorkingDay?.reference || 'None.'}</p><p><span className="font-bold">Remarks:</span> {selectedNonWorkingDay?.remarks || 'None.'}</p><p><span className="font-bold">Status:</span> {selectedNonWorkingDay?.is_active ? 'Active' : 'Inactive'}</p></div>{canManage && <button type="button" onClick={() => editNonWorkingDay(selectedNonWorkingDay)} className="mt-5 rounded-lg bg-green-700 px-3 py-2 text-xs font-bold text-white">Edit</button>}</CrudDetailsModal>
        <CrudFormModal open={nonWorkingDayFormOpen} mode={editingNonWorkingDay ? 'edit' : 'create'} icon="∷" title={editingNonWorkingDay ? 'Edit Non-Working Day' : 'Add Non-Working Day'} subtitle="Business calendar configuration" onClose={resetNonWorkingDay} onSubmit={submitNonWorkingDay} processing={nonWorkingDayForm.processing} errors={nonWorkingDayForm.errors} saveLabel={editingNonWorkingDay ? 'Save Changes' : 'Save Non-Working Day'}>
            <div className="grid gap-4 sm:grid-cols-2"><FloatingInput label="Date" type="date" required value={nonWorkingDayForm.data.date || ''} onChange={event => nonWorkingDayForm.setData('date', event.target.value)} error={nonWorkingDayForm.errors.date} /><FloatingInput label="Name / Description" required value={nonWorkingDayForm.data.name || ''} onChange={event => nonWorkingDayForm.setData('name', event.target.value)} error={nonWorkingDayForm.errors.name} /><FloatingSelect label="Type" required value={nonWorkingDayForm.data.type || ''} onChange={event => nonWorkingDayForm.setData('type', event.target.value)} error={nonWorkingDayForm.errors.type}><option value="NATIONAL_HOLIDAY">National Holiday</option><option value="LOCAL_HOLIDAY">Local Holiday</option><option value="SPECIAL_NON_WORKING_DAY">Special Non-Working Day</option><option value="OFFICE_DECLARED_NON_WORKING_DAY">Office-Declared Non-Working Day</option></FloatingSelect><FloatingSelect label="Scope" required value={nonWorkingDayForm.data.scope || ''} onChange={event => nonWorkingDayForm.setData('scope', event.target.value)} error={nonWorkingDayForm.errors.scope}><option value="NATIONAL">National</option><option value="DAVAO_ORIENTAL">Davao Oriental</option><option value="OFFICE">Office</option></FloatingSelect>{nonWorkingDayForm.data.scope === 'OFFICE' && <FloatingInput label="Office / Location" required value={nonWorkingDayForm.data.location || ''} onChange={event => nonWorkingDayForm.setData('location', event.target.value)} error={nonWorkingDayForm.errors.location} />}<FloatingInput label="Reference / Proclamation No. (optional)" value={nonWorkingDayForm.data.reference || ''} onChange={event => nonWorkingDayForm.setData('reference', event.target.value)} error={nonWorkingDayForm.errors.reference} /><FloatingSelect label="Status" required value={nonWorkingDayForm.data.is_active ? '1' : '0'} onChange={event => nonWorkingDayForm.setData('is_active', event.target.value === '1')} error={nonWorkingDayForm.errors.is_active}><option value="1">Active</option><option value="0">Inactive</option></FloatingSelect></div><FloatingTextarea label="Remarks (optional)" rows={3} value={nonWorkingDayForm.data.remarks || ''} onChange={event => nonWorkingDayForm.setData('remarks', event.target.value)} error={nonWorkingDayForm.errors.remarks} />
        </CrudFormModal>
    </AuthenticatedLayout>;
}

function SettingsSection({ title, children }) { return <section className="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900"><h2 className="mb-4 text-sm font-bold text-gray-900 dark:text-white">{title}</h2>{children}</section>; }

function DestinationCards({ cards, onPreview, previewing }) {
        return <SettingsSection title="Mapped Destinations"><p className="mb-5 text-xs text-gray-500 dark:text-gray-400">Each active destination has one recipient mapping. Preview actions use the same current reports, mapped TO/CC, template, and memorandum renderer used by automation.</p>{cards.length ? <div className="grid gap-4 xl:grid-cols-2">{cards.map(card => <article key={card.destination_key} className="rounded-xl border border-gray-200 p-4 dark:border-gray-700"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-bold text-gray-900 dark:text-white">{card.destination || 'Unmapped destination'}</h3><p className="mt-1 text-xs font-semibold text-gray-500 dark:text-gray-400">{card.destination_type}</p></div><span className={card.status === 'mapped' ? 'rounded-full bg-green-50 px-2.5 py-1 text-xs font-bold text-green-700 dark:bg-green-950/40 dark:text-green-300' : 'rounded-full bg-red-50 px-2.5 py-1 text-xs font-bold text-red-700 dark:text-red-300'}>{card.status === 'mapped' ? 'Active / Mapped' : 'Not Ready'}</span></div><dl className="mt-4 grid gap-2 text-sm"><div><dt className="text-xs font-bold uppercase tracking-wide text-gray-500">TO</dt><dd className="font-semibold">{card.recipient?.name || 'Default designation'}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-gray-500">ATTENTION</dt><dd>{card.recipient?.attention_line || 'Alert-type fallback by template'}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-gray-500">EMAIL</dt><dd>{card.recipient?.email || 'Not configured'}</dd></div><div><dt className="text-xs font-bold uppercase tracking-wide text-gray-500">CC</dt><dd>{(card.recipient?.cc_emails || []).join(', ') || 'None'}</dd></div></dl><div className="mt-4 flex flex-wrap gap-x-4 gap-y-1 text-xs text-gray-500"><span>{card.report_count} workflow report(s)</span><span>{card.due_soon_count} due in 3 days</span><span>{card.overdue_count} overdue</span></div><div className="mt-4 flex flex-wrap gap-2"><button type="button" disabled={previewing || card.status !== 'mapped' || card.due_soon_count < 1} onClick={() => onPreview(card.destination_key, 'DUE_SOON')} className="rounded-lg border border-green-700 px-3 py-2 text-xs font-bold text-green-700 hover:bg-green-50 disabled:cursor-not-allowed disabled:opacity-40 dark:border-green-400 dark:text-green-300">Preview 3-Day</button><button type="button" disabled={previewing || card.status !== 'mapped' || card.overdue_count < 1} onClick={() => onPreview(card.destination_key, 'OVERDUE')} className="rounded-lg border border-green-700 px-3 py-2 text-xs font-bold text-green-700 hover:bg-green-50 disabled:cursor-not-allowed disabled:opacity-40 dark:border-green-400 dark:text-green-300">Preview Overdue</button></div></article>)}</div> : <p className="rounded-xl border border-dashed border-gray-300 p-5 text-sm text-gray-500 dark:border-gray-700 dark:text-gray-400">No active recipient mappings are configured yet. Configure a Protected Area or Development / ENGP office mapping before previewing automation.</p>}</SettingsSection>;
}

function TemplateEditors({ title, description, templates, templateSettings, onChange }) {
    const labels = { protected_area_due_soon: '3-Day Reminder', protected_area_overdue: 'Overdue Warning', engp_due_soon: '3-Day Reminder', engp_overdue: 'Overdue Warning' };
    return <SettingsSection title={title}><p className="mb-5 text-xs text-gray-500 dark:text-gray-400">{description} Use the compact toolbar to format selected memorandum text. Subjects remain plain text.</p><div className="space-y-8">{templates.map(template => { const fields = templateSettings[template] || {}; return <section key={template} className="rounded-xl border border-gray-200 p-4 dark:border-gray-700"><div className="mb-4"><h3 className="font-bold text-gray-900 dark:text-white">{labels[template]}</h3></div><div className="grid gap-4 md:grid-cols-2"><FloatingInput label="Email Subject (plain text)" value={fields.subject || ''} onChange={event => onChange(template, 'subject', event.target.value)} /><ComplianceRichTextEditor label="Focal-person / Footer Label" value={fields.focal_footer_text || ''} onChange={value => onChange(template, 'focal_footer_text', value)} /></div><div className="mt-4 grid gap-4"><ComplianceRichTextEditor label="Introductory Paragraph" rows={3} value={fields.introductory_text || ''} onChange={value => onChange(template, 'introductory_text', value)} placeholder="Introductory paragraph" /><ComplianceRichTextEditor label="Instruction / Compliance Paragraph" rows={3} value={fields.instruction_text || ''} onChange={value => onChange(template, 'instruction_text', value)} placeholder="Instruction or compliance paragraph" /><ComplianceRichTextEditor label="Report Section Heading" rows={1} value={fields.report_heading || ''} onChange={value => onChange(template, 'report_heading', value)} placeholder="Report section heading" /><ComplianceRichTextEditor label="Closing / Compliance Paragraph" rows={3} value={fields.closing_text || ''} onChange={value => onChange(template, 'closing_text', value)} placeholder="Closing or compliance paragraph" /><ComplianceRichTextEditor label="Closing Directive" rows={1} value={fields.closing_directive || ''} onChange={value => onChange(template, 'closing_directive', value)} placeholder="Closing directive" /></div></section>; })}</div></SettingsSection>;
}
